def set_quantity(value):
    if value < 0:
        raise ValueError('quantity cannot be negative')
    return value
try:
    set_quantity(-2)
except ValueError as error:
    print(type(error).__name__)

def label(value):
    if not isinstance(value, str):
        raise TypeError('label must be text')
    return value.upper()
try:
    label(10)
except TypeError as error:
    print(str(error))

class OutOfStockError(Exception):
    pass
def reserve(stock):
    if stock == 0:
        raise OutOfStockError('no units available')
try:
    reserve(0)
except OutOfStockError:
    print('Reservation unavailable')

try:
    int('x')
except ValueError:
    print('record rejected')
    try:
        raise
    except ValueError:
        print('original error preserved')

class PaymentError(Exception):
    pass
class CardDeclinedError(PaymentError):
    pass
try:
    raise CardDeclinedError()
except PaymentError:
    print('Payment could not be completed')
